INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine Dokumenten-Datenbank dasselbe wie eine relationale Datenbank?', 2, '[{"text": "Nein", "correct": true, "because": "Verschiedene Strukturen"}, {"text": "Ja", "correct": false, "because": "Dokumente vs. Tabellen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptmerkmal hat eine Dokumenten-Datenbank?', 3, '[{"text": "Daten als Dokumente speichern", "correct": true, "because": "JSON/BSON-Format"}, {"text": "Tabellen mit Primärschlüssel", "correct": false, "because": "Relational"}, {"text": "Fest definierte Schemata", "correct": false, "because": "Flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Formate nutzen Dokumenten-Datenbanken?', 5, '[{"text": "JSON", "correct": true, "because": "Häufiges Format"}, {"text": "XML", "correct": true, "because": "Auch unterstützt"}, {"text": "CSV", "correct": false, "because": "Tabellenformat"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Dokumenten-Datenbanken sind schemalos. b) Sie nutzen immer SQL.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Oft NoSQL"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einer Dokumenten-Datenbank?', 4, '[{"text": "Datenstruktur", "correct": false, "because": "Wichtig für Zugriff"}, {"text": "Skalierbarkeit", "correct": false, "because": "Kernaspekt"}, {"text": "Papierformat", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Dokumenten-Datenbank nur JSON nutzt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch BSON, XML"}, {"text": "Ja", "correct": false, "because": "Verschiedene Formate"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches System ist ein Beispiel für eine Dokumenten-Datenbank?', 3, '[{"text": "MongoDB", "correct": true, "because": "Bekanntes NoSQL-System"}, {"text": "MySQL", "correct": false, "because": "Relational"}, {"text": "SQLite", "correct": false, "because": "Relational"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine Dokumenten-Datenbank?', 5, '[{"text": "Flexibilität", "correct": true, "because": "Schemalos"}, {"text": "Skalierbarkeit", "correct": true, "because": "Horizontale Skalierung"}, {"text": "Feste Tabellen", "correct": false, "because": "Nicht relational"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Dokumenten-Datenbanken speichern hierarchische Daten. b) Sie sind immer langsamer als relationale. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Geschwindigkeit variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine Dokumenten-Datenbank?', 4, '[{"text": "Datenbanksoftware", "correct": false, "because": "Grundlage"}, {"text": "Daten in Dokumenten", "correct": false, "because": "Kernmerkmal"}, {"text": "Feste Tabellenstruktur", "correct": true, "because": "Schemalos"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Dokumenten-Datenbanken immer NoSQL?', 2, '[{"text": "Ja", "correct": true, "because": "Typisches Merkmal"}, {"text": "Nein", "correct": false, "because": "Meist NoSQL"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Datenstrukturen passen zu Dokumenten-Datenbanken?', 4, '[{"text": "Hierarchische Daten", "correct": true, "because": "Verschachtelt"}, {"text": "Key-Value-Paare", "correct": true, "because": "Dokumentenbasis"}, {"text": "Tabellen mit Joins", "correct": false, "because": "Relational"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Dokumenten-Datenbanken keine Indizes nutzen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Indizes für Performance"}, {"text": "Ja", "correct": false, "because": "Indizes möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einer Dokumenten-Datenbank?', 3, '[{"text": "Flexibilität", "correct": true, "because": "Schemalos"}, {"text": "Feste Schemata", "correct": false, "because": "Nicht erforderlich"}, {"text": "Manuelle Struktur", "correct": false, "because": "Dynamisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Dokumenten-Datenbanken sind skalierbar. b) Sie nutzen immer relationale Joins.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Joins sind selten"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anwendungsfälle passen zu Dokumenten-Datenbanken?', 5, '[{"text": "Content-Management", "correct": true, "because": "Flexible Daten"}, {"text": "E-Commerce", "correct": true, "because": "Produktdaten"}, {"text": "Fest strukturiertes Banking", "correct": false, "because": "Relational besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer Dokumenten-Datenbank unwichtig?', 3, '[{"text": "Datenformat", "correct": false, "because": "JSON/XML wichtig"}, {"text": "Skalierung", "correct": false, "because": "Kernaspekt"}, {"text": "Papiergröße", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Unterstützen Dokumenten-Datenbanken Transaktionen?', 3, '[{"text": "Ja", "correct": true, "because": "In modernen Systemen"}, {"text": "Nein", "correct": false, "because": "Teilweise möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Dokumenten-Datenbanken für Big Data geeignet sind?', 2, '[{"text": "Ja", "correct": true, "because": "Skalierbar"}, {"text": "Nein", "correct": false, "because": "Big Data tauglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature ist für Dokumenten-Datenbanken zentral?', 4, '[{"text": "Schemalosigkeit", "correct": true, "because": "Flexible Struktur"}, {"text": "Feste Tabellen", "correct": false, "because": "Relational"}, {"text": "Manuelle Joins", "correct": false, "because": "Nicht üblich"}]');
